        pass

    @property
    @abstractmethod
    def reason(self) -> str:
        pass

    @property
    @abstractmethod
    def netloc(self) -> str:
        pass

    @property
    @abstractmethod
    def urlext(self) -> str:
        return self.url[len(self.netloc) :]

    @property
    @abstractmethod
    def in_progress(self) -> bool:
        pass

    @property
    @abstractmethod
    def last_update(self) -> datetime.datetime:
        pass

    @abstractmethod
    def receive_data(self, data: bytes):
        pass

    @abstractmethod
    def send_data(self, data: bytes):
        pass

    @property
    @abstractmethod
    def protocol(self) -> str:
        pass

